WITH valid_inventory AS (SELECT *, DATE_TRUNC('MONTH', last_restock) last_restock_period FROM inventory WHERE MONTH(last_restock) IN (7, 9, 12)), last_restock_period_cohort_summary AS (SELECT CASE WHEN YEAR(last_restock_period) < 2024 THEN 'before_2024' WHEN YEAR(last_restock_period) = 2024 THEN '2024' ELSE 'after_2024' END last_restock_period_cohort, MIN(quantity) min_quantity FROM valid_inventory GROUP BY CASE WHEN YEAR(last_restock_period) < 2024 THEN 'before_2024' WHEN YEAR(last_restock_period) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT * FROM last_restock_period_cohort_summary;
